    "id": "viewport",
    "fix_code": "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">",
    "fix_explanation": "This tag tells mobile browsers to scale the page to the device's screen width instead of rendering it at desktop size. Without it, the site will appear zoomed out and unreadable on phones and tablets.",
    "fix_location": "Paste inside <head>, immediately after <meta charset=\"utf-8\">"
  },
  {
    "id": "heading-h1",
    "fix_code": "<h1>Jane Doe — UX Designer &amp; Illustrator</h1>",
    "fix_explanation": "Every page needs exactly one H1 that describes its primary topic; search engines use it as a strong relevance signal. Place it as the first visible heading in your page's <body>, typically above your intro paragraph or hero section.",
    "fix_location": "Paste as the first element inside <body>, before any other headings or content"
  },
  {
    "id": "meta-description",
    "fix_code": "<meta name=\"description\" content=\"Jane Doe is a UX Designer &amp; Illustrator crafting intuitive digital experiences and bold visual art. Explore her portfolio of UI design and illustration work.\">",
    "fix_explanation": "The meta description is the snippet shown under your page title in search results; a compelling, keyword-rich description (120–160 characters) improves click-through rates. This one is 154 characters and highlights Jane's core disciplines.",
    "fix_location": "Paste inside <head>, after the <title> tag and before the existing Open Graph meta tags"
  }
]
